#include <iostream>
#include <string>
using namespace std;

int main() {
    int n, d;
    cin >> n >> d;
    string s;
    cin >> s;
    int cur = 1, jumps = 0;
    while (cur < n) {
        int nxt = 0;
        for (int i = cur + 1; i <= cur + d && i <= n; ++i) {
            if (s[i - 1] == '1') nxt = i;
        }
        if (nxt == 0) {
            cout << -1 << endl;
            return 0;
        }
        cur = nxt;
        ++jumps;
    }
    cout << jumps << endl;
    return 0;
}

