import sys
from collections import deque

def beautiful(s):
    for i in range(len(s)-1):
        if s[i] == s[i+1]:
            return False
    return True

def possible(n, m, s, t):
    start = (s, t)
    if beautiful(s) and beautiful(t):
        return True
    visited = set([start])
    q = deque([start])
    while q:
        cs, ct = q.popleft()
        if len(cs) >= 2:
            ns = cs[:-1]; nt = ct + cs[-1]
            if beautiful(ns) and beautiful(nt):
                return True
            if (ns, nt) not in visited:
                visited.add((ns, nt)); q.append((ns, nt))
        if len(ct) >= 2:
            ns = cs + ct[-1]; nt = ct[:-1]
            if beautiful(ns) and beautiful(nt):
                return True
            if (ns, nt) not in visited:
                visited.add((ns, nt)); q.append((ns, nt))
    return False

def solve():
    data = sys.stdin.read().strip().split()
    if not data: return
    it = iter(data)
    t = int(next(it))
    out = []
    for _ in range(t):
        n = int(next(it)); m = int(next(it))
        s = next(it); tstr = next(it)
        out.append("YES" if possible(n, m, s, tstr) else "NO")
    print("\n".join(out))

if __name__ == "__main__":
    solve()

