#include <vector>
using namespace std;
int main() {
    int n; cin >> n;
    vector<long long> cnt(100005, 0);
    int max_val = 0;
    for (int i=0; i<n; i++) { int x; cin >> x; cnt[x]++; if(x>max_val) max_val=x; }
    vector<long long> dp(max_val+1, 0);
    if(max_val>=1) dp[1] = cnt[1]*1;
    for (int i=2; i<=max_val; i++) dp[i] = max(dp[i-1], dp[i-2] + cnt[i]*i);
    cout << dp[max_val] << endl;
    return 0;
}

