using namespace std;
const int MOD = 1000000007;
int main() {
    int n, k;
    if (!(cin >> n >> k)) return 0;
    vector<vector<int>> dp(k+1, vector<int>(n+1, 0));
    for (int j = 1; j <= n; ++j) dp[1][j] = 1;
    for (int i = 2; i <= k; ++i) {
        for (int d = 1; d <= n; ++d) {
            if (dp[i-1][d] == 0) continue;
            for (int j = d; j <= n; j += d) {
                dp[i][j] = (dp[i][j] + dp[i-1][d]) % MOD;
            }
        }
    }
    long long ans = 0;
    for (int j = 1; j <= n; ++j) ans = (ans + dp[k][j]) % MOD;
    cout << ans << endl;
    return 0;
}

