#include <iostream>
#include <vector>
using namespace std;
const int MOD = 1000000007;
const int MAXN = 1000005;
long long fact[MAXN], invfact[MAXN];
long long powmod(long long x, long long y) {
    long long res = 1;
    while (y) {
        if (y & 1) res = res * x % MOD;
        x = x * x % MOD; y >>= 1;
    }
    return res;
}
void precompute(int n) {
    fact[0] = 1;
    for (int i = 1; i <= n; i++) fact[i] = fact[i-1] * i % MOD;
    invfact[n] = powmod(fact[n], MOD-2);
    for (int i = n; i >= 1; i--) invfact[i-1] = invfact[i] * i % MOD;
}
long long comb(int n, int k) {
    if (k < 0 || k > n) return 0;
    return fact[n] * invfact[k] % MOD * invfact[n-k] % MOD;
}
bool isGood(long long s, int a, int b) {
    if (s == 0) return false;
    while (s) {
        int d = s % 10;
        if (d != a && d != b) return false;
        s /= 10;
    }
    return true;
}
int main() {
    int a, b, n;
    cin >> a >> b >> n;
    precompute(n);
    long long ans = 0;
    for (int i = 0; i <= n; i++) {
        long long sum = 1LL * n * a + 1LL * i * (b - a);
        if (isGood(sum, a, b)) {
            ans = (ans + comb(n, i)) % MOD;
        }
    }
    cout << ans << endl;
    return 0;
}

