#include <bits/stdc++.h>
using namespace std;

const int S = 700;
int n, m;
int a[200005], b[200005], pos_a[200005], pb[200005];
vector<int> blk[300];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin >> n >> m;
    for (int i = 1; i <= n; i++) {
        cin >> a[i];
        pos_a[a[i]] = i;
    }
    for (int i = 1; i <= n; i++) {
        cin >> b[i];
        pb[b[i]] = i;
    }
    int nb = (n + S - 1) / S;
    for (int i = 1; i <= n; i++) {
        int v = a[i];
        blk[(i - 1) / S].push_back(pb[v]);
    }
    for (int i = 0; i < nb; i++) sort(blk[i].begin(), blk[i].end());

    while (m--) {
        int type; cin >> type;
        if (type == 1) {
            int la, ra, lb, rb; cin >> la >> ra >> lb >> rb;
            int bl = (la - 1) / S, br = (ra - 1) / S;
            int ans = 0;
            if (bl == br) {
                for (int i = la; i <= ra; i++) {
                    int v = a[i];
                    if (pb[v] >= lb && pb[v] <= rb) ans++;
                }
            } else {
                for (int i = la; i <= (bl + 1) * S; i++) {
                    if (i > n) break;
                    int v = a[i];
                    if (pb[v] >= lb && pb[v] <= rb) ans++;
                }
                for (int i = br * S + 1; i <= ra; i++) {
                    int v = a[i];
                    if (pb[v] >= lb && pb[v] <= rb) ans++;
                }
                for (int k = bl + 1; k < br; k++) {
                    ans += upper_bound(blk[k].begin(), blk[k].end(), rb) - lower_bound(blk[k].begin(), blk[k].end(), lb);
                }
            }
            cout << ans << '\n';
        } else {
            int x, y; cin >> x >> y;
            int u = b[x], v = b[y];
            swap(b[x], b[y]);
            int opu = pb[u], opv = pb[v];
            pb[u] = y; pb[v] = x;
            int bu = (pos_a[u] - 1) / S;
            auto& vu = blk[bu];
            vu.erase(lower_bound(vu.begin(), vu.end(), opu));
            vu.insert(lower_bound(vu.begin(), vu.end(), y), y);
            int bv = (pos_a[v] - 1) / S;
            auto& vv = blk[bv];
            vv.erase(lower_bound(vv.begin(), vv.end(), opv));
            vv.insert(lower_bound(vv.begin(), vv.end(), x), x);
        }
    }
    return 0;
}

