#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int t; cin >> t;
    while (t--) {
        int n; cin >> n;
        vector<int> r(n+1);
        vector<int> indeg(n+1, 0);
        for (int i=1; i<=n; ++i) { cin >> r[i]; indeg[r[i]]++; }
        // 找环：拓扑删入度为0的点
        queue<int> q;
        for (int i=1; i<=n; ++i) if (indeg[i]==0) q.push(i);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            int v = r[u];
            if (--indeg[v] == 0) q.push(v);
        }
        vector<bool> incycle(n+1, false);
        for (int i=1; i<=n; ++i) if (indeg[i] > 0) incycle[i] = true;
        // 非环节点 DP
        vector<long long> T(n+1, 0);
        vector<int> indeg2(n+1, 0);
        for (int i=1; i<=n; ++i) if (!incycle[i]) { T[i] = 1; indeg2[r[i]]++; }
        queue<int> q2;
        for (int i=1; i<=n; ++i) if (!incycle[i] && indeg2[i]==0) q2.push(i);
        while (!q2.empty()) {
            int u = q2.front(); q2.pop();
            int v = r[u];
            if (!incycle[v]) {
                T[v] += T[u];
                if (--indeg2[v] == 0) q2.push(v);
            }
        }
        long long mx = 0;
        for (int i=1; i<=n; ++i) if (!incycle[i]) mx = max(mx, T[i]);
        cout << mx + 2 << "\n";
    }
    return 0;
}

