#include <bits/stdc++.h>
using namespace std;
const int MOD = 998244353;
struct Fenwick {
    int n;
    vector<long long> bit;
    Fenwick(int n): n(n), bit(n+1,0) {}
    void add(int i, long long v) {
        v %= MOD; if(v<0) v+=MOD;
        for (; i<=n; i+=i&-i) bit[i] = (bit[i]+v)%MOD;
    }
    long long query(int i) {
        long long s=0;
        for (; i>0; i-=i&-i) s = (s+bit[i])%MOD;
        return s;
    }
};
int main() {
    ios::sync_with_stdio(false); cin.tie(0);
    int n; cin >> n;
    vector<int> x(n), y(n), s(n);
    vector<int> vals;
    for (int i=0;i<n;i++) {
        cin >> x[i] >> y[i] >> s[i];
        vals.push_back(x[i]); vals.push_back(y[i]);
    }
    sort(vals.begin(), vals.end());
    vals.erase(unique(vals.begin(), vals.end()), vals.end());
    int m = vals.size();
    Fenwick tree(m);
    long long ans = (x[n-1] + 1) % MOD;
    for (int i=n-1;i>=0;i--) {
        int rx = lower_bound(vals.begin(), vals.end(), x[i]) - vals.begin() + 1;
        long long B = tree.query(rx - 1);
        long long c = (B + s[i]) % MOD;
        int ry = lower_bound(vals.begin(), vals.end(), y[i]) - vals.begin() + 1;
        tree.add(ry, c);
        long long diff = (x[i] - y[i]) % MOD;
        ans = (ans + c * diff) % MOD;
    }
    ans = (ans % MOD + MOD) % MOD;
    cout << ans << '\n';
    return 0;
}

