import sys
sys.setrecursionlimit(10000)

def solve():
    import sys
    input = sys.stdin.readline
    t = int(input())
    out = []
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))
        b = list(map(int, input().split()))
        base = sum(a[i] - b[i] for i in range(n))
        valA = [b[i] - 1 for i in range(n)]
        valB = [1 - a[i] for i in range(n)]
        from functools import lru_cache
        @lru_cache(None)
        def dfs(mask, turn):
            if mask == 0:
                return 0
            if turn == 0:
                best = -10**18
                for i in range(n):
                    if mask & (1 << i):
                        best = max(best, valA[i] + dfs(mask ^ (1 << i), 1))
                return best
            else:
                best = 10**18
                for i in range(n):
                    if mask & (1 << i):
                        best = min(best, valB[i] + dfs(mask ^ (1 << i), 0))
                return best
        ans = base + dfs((1 << n) - 1, 0)
        out.append(str(ans))
    print('\n'.join(out))

if __name__ == '__main__':
    solve()

