#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

const int MOD = 1000000007;

long long modpow(long long a, long long e) {
    long long res = 1;
    a %= MOD;
    while (e) {
        if (e & 1) res = res * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return res;
}

void solve() {
    int n, m;
    cin >> n >> m;
    vector<int> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    sort(a.begin(), a.end());
    vector<pair<int, long long>> vals;
    for (int i = 0; i < n; ) {
        int j = i;
        while (j < n && a[j] == a[i]) j++;
        vals.push_back({a[i], j - i});
        i = j;
    }
    long long ans = 0;
    vector<long long> b;
    for (int i = 0; i < (int)vals.size(); i++) {
        if (i > 0 && vals[i].first != vals[i-1].first + 1) {
            if ((int)b.size() >= m) {
                long long prod = 1;
                for (int j = 0; j < m; j++) prod = prod * b[j] % MOD;
                ans = (ans + prod) % MOD;
                for (int j = m; j < (int)b.size(); j++) {
                    prod = prod * modpow(b[j - m], MOD - 2) % MOD * b[j] % MOD;
                    ans = (ans + prod) % MOD;
                }
            }
            b.clear();
        }
        b.push_back(vals[i].second);
    }
    if ((int)b.size() >= m) {
        long long prod = 1;
        for (int j = 0; j < m; j++) prod = prod * b[j] % MOD;
        ans = (ans + prod) % MOD;
        for (int j = m; j < (int)b.size(); j++) {
            prod = prod * modpow(b[j - m], MOD - 2) % MOD * b[j] % MOD;
            ans = (ans + prod) % MOD;
        }
    }
    cout << ans << '\n';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    cin >> t;
    while (t--) solve();
    return 0;
}

