                total -= it->second - it->first + 1;
                st.erase(it);
            }
        };
        int s=1;
        for(int i=0;i<m;i++){
            if(a[i]<=s && s<b[i]) add(b[i], a[i]+n-1);
            else add(a[i], b[i]-1);
        }
        int ans = (int)total;
        for(s=1;s<n;s++){
            for(int i: by_a[s+1]){ rem(a[i], b[i]-1); add(b[i], a[i]+n-1); }
            for(int i: by_b[s+1]){ rem(b[i], a[i]+n-1); add(a[i], b[i]-1); }
            ans = min(ans, (int)total);
        }
        cout<<ans<<"\n";
    }
}

