int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long T;
    if (!(cin >> n >> T)) return 0;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    vector<long long> b = a;
    sort(b.begin(), b.end());
    long long sum = 0;
    for (int i = 0; i < n; i++) sum += b[i];
    int cnt = n;
    long long ans = 0;
    while (cnt > 0) {
        while (cnt > 0 && b[cnt - 1] > T) {
            sum -= b[cnt - 1];
            cnt--;
        }
        if (cnt == 0) break;
        if (sum <= T) {
            long long rounds = T / sum;
            ans += rounds * cnt;
            T -= rounds * sum;
        } else {
            for (int i = 0; i < n; i++) {
                if (a[i] <= T) {
                    T -= a[i];
                    ans++;
                }
            }
        }
    }
    cout << ans << "\n";
    return 0;
}

