#include <bits/stdc++.h>
using namespace std;

vector<int> solve(const string& s, int l, int r) {
    int n = s.size();
    vector<int> z(n);
    int L = 0, R = 0;
    for (int i = 1; i < n; ++i) {
        if (i <= R) z[i] = min(R - i + 1, z[i - L]);
        while (i + z[i] < n && s[z[i]] == s[i + z[i]]) z[i]++;
        if (i + z[i] - 1 > R) { L = i; R = i + z[i] - 1; }
    }
    vector<vector<int>> buck(n + 1);
    for (int i = 1; i < n; ++i) {
        int lim = min(z[i], n - i);
        if (lim > 0) buck[lim].push_back(i);
    }
    set<int> act;
    act.insert(0);
    vector<int> cnt(n + 1, 0);
    for (int x = n; x >= 1; --x) {
        for (int i : buck[x]) act.insert(i);
        int cur = 0, c = 1;
        while (true) {
            auto it = act.lower_bound(cur + x);
            if (it == act.end()) break;
            cur = *it; c++;
        }
        cnt[x] = c;
    }
    vector<int> ans(n + 1, 0);
    for (int x = 1; x <= n; ++x) if (cnt[x] > 0) ans[cnt[x]] = max(ans[cnt[x]], x);
    for (int k = n - 1; k >= 1; --k) ans[k] = max(ans[k], ans[k + 1]);
    vector<int> res;
    for (int k = l; k <= r; ++k) res.push_back(ans[k]);
    return res;
}

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int t; cin >> t;
    while (t--) {
        int n, l, r; cin >> n >> l >> r;
        string s; cin >> s;
        vector<int> res = solve(s, l, r);
        for (size_t i = 0; i < res.size(); ++i) cout << res[i] << (i + 1 == res.size() ? "" : " ");
        cout << '\n';
    }
    return 0;
}

