#include <iostream>
#include <vector>
#include <string>

using namespace std;

int n, m;
vector<string> board;
vector<vector<bool>> vis;
bool cycle_found = false;

void dfs(int r, int c, int pr, int pc, char color) {
    vis[r][c] = true;
    int dr[] = {1, -1, 0, 0};
    int dc[] = {0, 0, 1, -1};
    for (int i = 0; i < 4; ++i) {
        int nr = r + dr[i];
        int nc = c + dc[i];
        if (nr < 0 || nr >= n || nc < 0 || nc >= m) continue;
        if (board[nr][nc] != color) continue;
        if (!vis[nr][nc]) {
            dfs(nr, nc, r, c, color);
            if (cycle_found) return;
        } else {
            if (nr != pr || nc != pc) {
                cycle_found = true;
                return;
            }
        }
    }
}

int main() {
    cin >> n >> m;
    board.resize(n);
    for (int i = 0; i < n; ++i) cin >> board[i];
    vis.assign(n, vector<bool>(m, false));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (!vis[i][j]) {
                dfs(i, j, -1, -1, board[i][j]);
                if (cycle_found) {
                    cout << "Yes" << endl;
                    return 0;
                }
            }
        }
    }
    cout << "No" << endl;
    return 0;
}

