int mex(const vector<int>& a, int l, int r) {
    unordered_set<int> s(a.begin()+l, a.begin()+r+1);
    int m=0; while(s.count(m)) m++; return m;
}
vector<pair<int,int>> bfs_block(vector<int> init, int L) {
    vector<int> target(L, L);
    queue<vector<int>> q;
    map<vector<int>, pair<vector<int>, pair<int,int>>> par;
    q.push(init); par[init] = {{}, {-1,-1}};
    while(!q.empty()) {
        auto cur = q.front(); q.pop();
        if(cur == target) {
            vector<pair<int,int>> ops;
            auto s = cur;
            while(par[s].second.first != -1) {
                ops.push_back(par[s].second);
                s = par[s].first;
            }
            reverse(ops.begin(), ops.end());
            return ops;
        }
        for(int i=0;i<L;i++) for(int j=i;j<L;j++) {
            int m = mex(cur, i, j);
            auto nxt = cur;
            for(int k=i;k<=j;k++) nxt[k]=m;
            if(!par.count(nxt)) {
                par[nxt] = {cur, {i+1, j+1}};
                q.push(nxt);
            }
        }
