#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k;
    cin >> n >> k;
    string s;
    cin >> s;
    vector<long long> dp(n+1, 0);
    using P = pair<long long, int>;
    priority_queue<P, vector<P>, greater<P>> pq;
    for (int i = 1; i <= n; ++i) {
        while (!pq.empty() && pq.top().second < i) pq.pop();
        long long cur = pq.empty() ? LLONG_MAX : pq.top().first;
        dp[i] = dp[i-1] + i;
        if (cur < dp[i]) dp[i] = cur;
        if (s[i-1] == '1') {
            int R = min(n, i + k);
            long long C = dp[max(0, i - k - 1)] + i;
            pq.push({C, R});
        }
    }
    cout << dp[n] << "\n";
    return 0;
}

