#include <iostream>
#include <string>
#include <algorithm>
using namespace std;

struct Node {
    int open, close, mat;
    Node() : open(0), close(0), mat(0) {}
    Node(char c) {
        if (c == '(') { open = 1; close = 0; mat = 0; }
        else { open = 0; close = 1; mat = 0; }
    }
};

Node merge(Node L, Node R) {
    int m = min(L.open, R.close);
    Node res;
    res.mat = L.mat + R.mat + m;
    res.open = L.open + R.open - m;
    res.close = L.close + R.close - m;
    return res;
}

const int MAXN = 1000005;
Node tree[4 * MAXN];
string s;

void build(int v, int tl, int tr) {
    if (tl == tr) {
        tree[v] = Node(s[tl - 1]);
        return;
    }
    int tm = (tl + tr) / 2;
    build(v*2, tl, tm);
    build(v*2+1, tm+1, tr);
    tree[v] = merge(tree[v*2], tree[v*2+1]);
}

Node query(int v, int tl, int tr, int l, int r) {
    if (l > r) return Node();
    if (tl == l && tr == r) return tree[v];
    int tm = (tl + tr) / 2;
    if (r <= tm) return query(v*2, tl, tm, l, r);
    if (l > tm) return query(v*2+1, tm+1, tr, l, r);
    return merge(query(v*2, tl, tm, l, tm), query(v*2+1, tm+1, tr, tm+1, r));
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    if (!(cin >> s)) return 0;
    int n = s.size();
    build(1, 1, n);
    int m;
    cin >> m;
    while (m--) {
        int l, r;
        cin >> l >> r;
        Node ans = query(1, 1, n, l, r);
        cout << ans.mat * 2 << "\n";
    }
    return 0;
}

