#include <set>
#include <utility>
using namespace std;
using pii = pair<int,int>;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    if (!(cin >> t)) return 0;
    while (t--) {
        string s;
        cin >> s;
        int x = 0, y = 0;
        long long time = 0;
        set<pair<pii, pii>> vis;
        for (char c : s) {
            int nx = x, ny = y;
            if (c == 'N') ny++;
            else if (c == 'S') ny--;
            else if (c == 'E') nx++;
            else if (c == 'W') nx--;
            pii a = {x, y}, b = {nx, ny};
            if (a > b) swap(a, b);
            if (vis.find({a, b}) != vis.end()) time += 1;
            else { time += 5; vis.insert({a, b}); }
            x = nx; y = ny;
        }
        cout << time << '\n';
    }
    return 0;
}

