#include <bits/stdc++.h>
using namespace std;
const int MOD = 1000000007;
long long fact[7], invfact[7];
long long power(long long a, long long b) {
    long long res=1;
    while(b) { if(b&1) res=res*a%MOD; a=a*a%MOD; b>>=1; }
    return res;
}
long long C(long long n, int k) {
    if(k<0 || k>n) return 0;
    long long res=1;
    for(int i=0;i<k;i++) res = res * ((n-i)%MOD) % MOD;
    res = res * invfact[k] % MOD;
    return res;
}
int main() {
    fact[0]=1; for(int i=1;i<=6;i++) fact[i]=fact[i-1]*i%MOD;
    invfact[6] = power(fact[6], MOD-2);
    for(int i=5;i>=0;i--) invfact[i]=invfact[i+1]*(i+1)%MOD;
    long long m; cin>>m;
    string s = to_string(m);
    int len = s.length();
    int dp[11][2][11] = {0};
    dp[0][1][0]=1;
    for(int i=0;i<len;i++) {
        for(int t=0;t<2;t++) {
            for(int c=0;c<=i;c++) {
                if(!dp[i][t][c]) continue;
                int lim = t ? s[i]-'0' : 9;
                for(int d=0;d<=lim;d++) {
                    int nt = t && (d==lim);
                    int nc = c + (d==4 || d==7);
                    dp[i+1][nt][nc] = (dp[i+1][nt][nc] + dp[i][t][c]) % MOD;
                }
            }
        }
    }
    vector<long long> cnt(11,0);
    for(int c=0;c<=len;c++) cnt[c] = (dp[len][0][c] + dp[len][1][c]) % MOD;
    cnt[0] = (cnt[0] - 1 + MOD) % MOD;
    long long ans = 0;
    for(int k=0;k<=9;k++) {
        if(cnt[k]==0) continue;
        vector<vector<long long>> dp2(7, vector<long long>(61, 0));
        dp2[0][0]=1;
        for(int c=0;c<=9;c++) {
            long long avail = cnt[c] - (c==k?1:0);
            if(avail<0) avail=0;
            vector<vector<long long>> ndp2(7, vector<long long>(61, 0));
            for(int taken=0;taken<=6;taken++) {
                for(int sum=0;sum<=54;sum++) {
                    if(dp2[taken][sum]==0) continue;
                    for(int pick=0; pick<=min(6-taken, (int)min(avail, (long long)6)); pick++) {
                        long long ways = C(avail, pick);
                        ndp2[taken+pick][sum + c*pick] = (ndp2[taken+pick][sum + c*pick] + dp2[taken][sum] * ways) % MOD;
                    }
                }
            }
            dp2 = ndp2;
        }
        long long ways = 0;
        for(int sum=0; sum<k; sum++) ways = (ways + dp2[6][sum]) % MOD;
        ans = (ans + cnt[k] * ways % MOD * 720) % MOD;
    }
    cout << ans << endl;
    return 0;
}

