import sys
sys.setrecursionlimit(10000)
def solve():
    data=sys.stdin.read().strip().split()
    if not data: return
    it=iter(data)
    t=int(next(it))
    out=[]
    for _ in range(t):
        n=int(next(it))
        cols=[[int(next(it)) for _ in range(n)] for __ in range(3)]
        N=2*n
        adj=[[] for _ in range(N)]
        for j in range(n):
            lits=[]
            for i in range(3):
                v=cols[i][j]
                idx=abs(v)-1
                lit=2*idx if v>0 else 2*idx+1
                lits.append(lit)
            for a in range(3):
                for b in range(3):
                    if a!=b:
                        adj[lits[a]^1].append(lits[b])
        index=[0]*N; low=[0]*N; onstack=[False]*N; stack=[]; idxc=[0]; scc=[0]*N; cnt=[0]
        def sc(v):
            index[v]=low[v]=idxc[0]; idxc[0]+=1
            stack.append(v); onstack[v]=True
            for w in adj[v]:
                if index[w]==0:
                    sc(w); low[v]=min(low[v],low[w])
                elif onstack[w]:
                    low[v]=min(low[v],index[w])
            if low[v]==index[v]:
                while True:
                    w=stack.pop(); onstack[w]=False; scc[w]=cnt[0]
