            for a in range(3):
                for b in range(3):
                    if a!=b:
                        adj[lits[a]^1].append(lits[b])
        index=[0]*N; low=[0]*N; onstack=[False]*N; stack=[]; idxc=[0]; scc=[0]*N; cnt=[0]
