#include <bits/stdc++.h>
using namespace std;

// 计算数组段 [0, len-1] 的独立最大匹配数（返回匹配长度）
int calc(const vector<int>& a, const vector<int>& b) {
    int n = a.size();
    if (n == 0) return 0;
    unordered_set<int> Sa_even, Sb_even, Sa_odd, Sb_odd;
    bool common_even = false, common_odd = false;
    int match_pos = -1; // 0-based 从右数第一个匹配
    for (int i = n-1; i >= 0; --i) {
        bool match = false;
        if (a[i] == b[i]) match = true;
        else {
            if (Sa_even.count(b[i]) || Sb_odd.count(b[i])) match = true;
            else if (Sb_even.count(a[i]) || Sa_odd.count(a[i])) match = true;
            else if (common_even || common_odd) match = true;
        }
        if (match) {
            match_pos = i;
            break;
        } else {
            // 将当前 i 的值作为向左一步（奇距）的源
            if (Sa_even.count(a[i]) == 0) {
                if (Sb_even.count(a[i])) common_even = true;
                Sa_odd.insert(a[i]);
            }
            if (Sb_even.count(b[i]) == 0) {
                if (Sa_even.count(b[i])) common_even = true;
                Sb_odd.insert(b[i]);
            }
            // 距离全部 +1：偶距变为奇距，奇距变为偶距
            swap(Sa_even, Sa_odd);
            swap(Sb_even, Sb_odd);
        }
    }
    if (match_pos == -1) return 0;
    return match_pos + 1; // 0-based 左端到 match_pos 的长度
}

void solve() {
    int n; cin >> n;
    vector<int> a(n), b(n);
    for (int i=0;i<n;++i) cin>>a[i];
    for (int i=0;i<n;++i) cin>>b[i];
    // 后缀匹配数 suf[i] = calc(a[i..n-1], b[i..n-1])
    vector<int> suf(n+2, 0);
    for (int i=n-1; i>=0; --i) {
        int len = calc(vector<int>(a.begin()+i, a.end()), vector<int>(b.begin()+i, b.end()));
        suf[i] = len;
    }
    // 前缀匹配数 pref[i] = calc(a[0..i], b[0..i])
    vector<int> pref(n+2, 0);
    for (int i=0; i<n; ++i) {
        int len = calc(vector<int>(a.begin(), a.begin()+i+1), vector<int>(b.begin(), b.begin()+i+1));
        pref[i] = len;
    }
    int ans = suf[0]; // 不删除
    for (int p=0; p<n; ++p) {
        int left = (p>0 ? pref[p-1] : 0);
        int right = (p+1<n ? suf[p+1] : 0);
        ans = max(ans, left + right);
    }
    cout << ans << "\n";
}

int main() {
    ios::sync_with_stdio(false); cin.tie(0);
    int t; cin >> t;
    while (t--) solve();
    return 0;
}

