#include <bits/stdc++.h>
using namespace std;
const int MOD = 1000000007;
long long power(long long a, long long b) {
    long long res = 1;
    a %= MOD;
    while (b) {
        if (b & 1) res = res * a % MOD;
        a = a * a % MOD;
        b >>= 1;
    }
    return res;
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int m;
    if (!(cin >> m)) return 0;
    vector<int> mu(m + 1, 0);
    vector<bool> isprime(m + 1, true);
    vector<int> primes;
    mu[1] = 1; isprime[0] = isprime[1] = false;
    for (int i = 2; i <= m; i++) {
        if (isprime[i]) {
            primes.push_back(i);
            mu[i] = -1;
        }
        for (int p : primes) {
            if (i * p > m) break;
            isprime[i * p] = false;
            if (i % p == 0) {
                mu[i * p] = 0;
                break;
            } else {
                mu[i * p] = -mu[i];
            }
        }
    }
    long long ans = 1; // corresponds to the initial 1
    for (int d = 2; d <= m; d++) {
        if (mu[d] == 0) continue;
        long long f = m / d;
        long long term = f * power(m - f, MOD - 2) % MOD;
        if (mu[d] == 1) {
            ans = (ans - term + MOD) % MOD;
        } else { // mu[d] == -1
            ans = (ans + term) % MOD;
        }
    }
    cout << ans << "\n";
    return 0;
}

