import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it)); m = int(next(it))
    grid = []
    j1 = None; j2 = None
    used = set()
    for r in range(n):
        row = []
        for c in range(m):
            s = next(it)
            row.append(s)
            if s == 'J1': j1 = (r,c)
            elif s == 'J2': j2 = (r,c)
            else: used.add(s)
        grid.append(row)
    ranks = '23456789TJQKA'; suits = 'CDHS'
    avail = [r+s for r in ranks for s in suits if r+s not in used]
    def check(r,c,g):
        su = set(); ra = set()
        for i in range(3):
            for j in range(3):
                card = g[r+i][c+j]
                su.add(card[1]); ra.add(card[0])
        return len(su)==1 or len(ra)==9
    sq = [(r,c) for r in range(n-2) for c in range(m-2)]
    def find(g):
        for i in range(len(sq)):
            r1,c1 = sq[i]
            if not check(r1,c1,g): continue
            for j in range(len(sq)):
                if i==j: continue
                r2,c2 = sq[j]
                if r1+2>=r2 and r2+2>=r1 and c1+2>=c2 and c2+2>=c1: continue
                if check(r2,c2,g):
                    return (r1,c1,r2,c2)
        return None
    if j1 is None and j2 is None:
        res = find(grid)
        if res:
            r1,c1,r2,c2 = res
            print('Solution exists.')
            print('There are no jokers.')
            print(f'Put the first square to ({r1+1}, {c1+1}).')
            print(f'Put the second square to ({r2+1}, {c2+1}).')
            return
    elif j1 is not None and j2 is None:
        rj,cj = j1
        for card in avail:
            g = [row[:] for row in grid]; g[rj][cj]=card
            res = find(g)
            if res:
                r1,c1,r2,c2 = res
                print('Solution exists.')
                print(f'Replace J1 with {card}.')
                print(f'Put the first square to ({r1+1}, {c1+1}).')
                print(f'Put the second square to ({r2+1}, {c2+1}).')
                return
    elif j1 is None and j2 is not None:
        rj,cj = j2
        for card in avail:
            g = [row[:] for row in grid]; g[rj][cj]=card
            res = find(g)
            if res:
                r1,c1,r2,c2 = res
                print('Solution exists.')
                print(f'Replace J2 with {card}.')
                print(f'Put the first square to ({r1+1}, {c1+1}).')
                print(f'Put the second square to ({r2+1}, {c2+1}).')
                return
    else:
        r1j,c1j = j1; r2j,c2j = j2
        for card1 in avail:
            for card2 in avail:
                if card1==card2: continue
                g = [row[:] for row in grid]
                g[r1j][c1j]=card1; g[r2j][c2j]=card2
                res = find(g)
                if res:
                    r1,c1,r2,c2 = res
                    print('Solution exists.')
                    print(f'Replace J1 with {card1} and J2 with {card2}.')
                    print(f'Put the first square to ({r1+1}, {c1+1}).')
                    print(f'Put the second square to ({r2+1}, {c2+1}).')
                    return
    print('No solution.')

if __name__ == '__main__':
    solve()

