#include <bits/stdc++.h>
using namespace std;
const int N = 200005;
bool covered[N], yes[N];
int nxt[N], prv[N];
int find_nxt(int i){ if(i>N-1) return N; if(!covered[i]) return i; return nxt[i]=find_nxt(nxt[i]); }
int find_prv(int i){ if(i<1) return 0; if(!covered[i]) return i; return prv[i]=find_prv(prv[i]); }
set<pair<int,int>> S;
int main(){
    ios::sync_with_stdio(false); cin.tie(0);
    int n,q; cin>>n>>q;
    for(int i=1;i<=n+1;i++) nxt[i]=i;
    for(int i=0;i<=n;i++) prv[i]=i;
    while(q--){
        int t; cin>>t;
        if(t==0){
            int l,r,x; cin>>l>>r>>x;
            if(x==0){
                int i = find_nxt(l);
                while(i<=r){
                    covered[i]=true;
                    nxt[i]=find_nxt(i+1);
                    prv[i]=find_prv(i-1);
                    i=find_nxt(i);
                }
                vector<pair<int,int>> toadd;
                auto it = S.lower_bound({l,0});
                if(it!=S.begin()) --it;
                while(it!=S.end() && it->first <= r){
                    int il=it->first, ir=it->second;
                    if(ir >= l){
                        int nl = find_nxt(il);
                        int nr = find_prv(ir);
                        if(nl<=nr){
                            if(nl==nr) yes[nl]=true;
                            else toadd.push_back({nl,nr});
                        }
                        it = S.erase(it);
                    } else ++it;
                }
                for(auto& p: toadd) S.insert(p);
            } else {
                int nl = find_nxt(l);
                int nr = find_prv(r);
                if(nl<=nr){
                    if(nl==nr) yes[nl]=true;
                    else S.insert({nl,nr});
                }
            }
        } else {
            int j; cin>>j;
            if(covered[j]) cout<<"NO\n";
            else if(yes[j]) cout<<"YES\n";
            else cout<<"N/A\n";
        }
    }
    return 0;
}

