#include <iostream>
#include <cstring>
using namespace std;

int x0, y0, n, d;
int vx[20], vy[20];
char vis[410][410][2][2][2]; // 0未访问,1赢,2输
const int OFF = 200;

bool dfs(int x, int y, int turn, int au, int du) {
    if (vis[x+OFF][y+OFF][turn][au][du]) return vis[x+OFF][y+OFF][turn][au][du] == 1;
    bool can = false;
    if (turn == 0) { // Anton
        for (int i = 0; i < n; ++i) {
            int nx = x + vx[i], ny = y + vy[i];
            if (nx*nx + ny*ny <= d*d) {
                if (!dfs(nx, ny, 1, au, du)) can = true;
            }
        }
        if (au == 0) {
            int nx = y, ny = x;
            if (!dfs(nx, ny, 1, 1, du)) can = true;
        }
    } else { // Dasha
        for (int i = 0; i < n; ++i) {
            int nx = x + vx[i], ny = y + vy[i];
            if (nx*nx + ny*ny <= d*d) {
                if (!dfs(nx, ny, 0, au, du)) can = true;
            }
        }
        if (du == 0) {
            int nx = y, ny = x;
            if (!dfs(nx, ny, 0, au, 1)) can = true;
        }
    }
    vis[x+OFF][y+OFF][turn][au][du] = can ? 1 : 2;
    return can;
}

int main() {
    cin >> x0 >> y0 >> n >> d;
    for (int i = 0; i < n; ++i) cin >> vx[i] >> vy[i];
    memset(vis, 0, sizeof(vis));
    bool anton_wins = dfs(x0, y0, 0, 0, 0);
    cout << (anton_wins ? "Anton" : "Dasha") << endl;
    return 0;
}

