#include <bits/stdc++.h>
using namespace std;

struct Group {
    long long total = 0;
    unordered_map<int, int> freq;
    long long add(int v) {
        long long res = total - freq[v];
        total++;
        freq[v]++;
        return res;
    }
};

void solve() {
    int n; cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    map<pair<int,int>, Group> mA, mB, mC;
    long long ans = 0;
    for (int i = 0; i + 2 < n; i++) {
        int x = a[i], y = a[i+1], z = a[i+2];
        ans += mA[{y, z}].add(x);
        ans += mB[{x, z}].add(y);
        ans += mC[{x, y}].add(z);
    }
    cout << ans << '\n';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t; cin >> t;
    while (t--) solve();
    return 0;
}

