int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    if (!(cin >> n >> q)) return 0;
    deque<long long> dq;
    vector<long long> a(n);
    long long mx = 0;
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
        dq.push_back(a[i]);
        if (a[i] > mx) mx = a[i];
    }
    vector<pair<long long, long long>> ops(n);
    for (int i = 0; i < n; ++i) {
        long long A = dq.front(); dq.pop_front();
        long long B = dq.front(); dq.pop_front();
        ops[i] = {A, B};
        if (A > B) { dq.push_front(A); dq.push_back(B); }
        else { dq.push_front(B); dq.push_back(A); }
    }
    vector<long long> rest;
    dq.pop_front();
    while (!dq.empty()) { rest.push_back(dq.front()); dq.pop_front(); }
    for (int i = 0; i < q; ++i) {
        long long m; cin >> m;
        if (m <= n) cout << ops[m-1].first << ' ' << ops[m-1].second << '\n';
        else { long long idx = (m - n - 1) % (n - 1); cout << mx << ' ' << rest[idx] << '\n'; }
    }
    return 0;
}

