    for (int i = 1; i <= m; i++) fact[i] = fact[i - 1] * i;
    ll step = 0;
    while (q--) {
        int type;
        cin >> type;
        if (type == 2) {
            ll x;
            cin >> x;
            step += x;
        } else {
            int l, r;
            cin >> l >> r;
            ll sum = 0;
            int pref_end = n - m;
            int L = l, R = min(r, pref_end);
            if (L <= R) {
                sum += (ll)(L + R) * (R - L + 1) / 2;
            }
            int sL = max(l, pref_end + 1);
            if (sL <= r) {
                vector<int> nums(m);
                for (int i = 0; i < m; i++) nums[i] = n - m + 1 + i;
                vector<int> perm;
                ll s = step;
                for (int i = 0; i < m; i++) {
                    ll f = fact[m - 1 - i];
                    int idx = s / f;
                    s %= f;
                    perm.push_back(nums[idx]);
                    nums.erase(nums.begin() + idx);
                }
                for (int i = sL; i <= r; i++) {
                    int pos = i - (pref_end + 1);
                    sum += perm[pos];
                }
            }
            cout << sum << '\n';
        }
    }
    return 0;
}

