import sys
import math

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))
    out = []
    for _ in range(t):
        k = int(next(it))
        x = int(next(it))
        total = k * k
        if x > total:
            out.append(str(2 * k - 1))
        else:
            half = k * (k + 1) // 2
            if x <= half:
                n = math.isqrt(2 * x)
                while n * (n + 1) // 2 < x:
                    n += 1
                out.append(str(n))
            else:
                rem = total - x
                m = math.isqrt(2 * rem)
                while m * (m + 1) // 2 <= rem:
                    m += 1
                m -= 1
                out.append(str(2 * k - 1 - m))
    sys.stdout.write('\n'.join(out))

if __name__ == '__main__':
    solve()

