    data = sys.stdin.read().strip().split()
    if not data: return
    it = iter(data)
    n = int(next(it))
    p = [int(next(it)) for _ in range(n)]
    parent = list(range(n))
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb: parent[rb] = ra
    for i in range(n):
        row = next(it)
        for j in range(n):
            if row[j] == '1':
