#include <bits/stdc++.h>
using namespace std;
using ll = long long;

bool check(const vector<ll>& a, ll X) {
    int n = a.size();
    vector<ll> pref(n+1, 0);
    for (int i = 1; i <= n; i++) pref[i] = pref[i-1] + a[i-1];
    vector<ll> f(n+1, 1e18), g(n+1, 1e18);
    f[0] = 0; g[0] = 0;
    deque<int> dq; dq.push_back(0);
    for (int i = 1; i <= n; i++) {
        int L = lower_bound(pref.begin(), pref.end(), pref[i] - X) - pref.begin();
        while (!dq.empty() && dq.front() < L) dq.pop_front();
        if (!dq.empty()) g[i] = f[dq.front()];
        if (g[i-1] != 1e18) f[i] = g[i-1] + a[i-1];
        while (!dq.empty() && f[dq.back()] >= f[i]) dq.pop_back();
        dq.push_back(i);
    }
    return min(f[n], g[n]) <= X;
}

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int t; cin >> t;
    while (t--) {
        int n; cin >> n;
        vector<ll> a(n);
        ll sum = 0, mx = 0;
        for (int i = 0; i < n; i++) { cin >> a[i]; sum += a[i]; mx = max(mx, a[i]); }
        ll lo = mx, hi = sum, ans = hi;
        while (lo <= hi) {
            ll mid = lo + (hi - lo) / 2;
            if (check(a, mid)) { ans = mid; hi = mid - 1; }
            else lo = mid + 1;
        }
        cout << ans << '\n';
    }
    return 0;
}

