#include <bits/stdc++.h>
using namespace std;

void solve() {
    int n; cin >> n;
    vector<int> a(n+2);
    for (int i=1; i<=n; ++i) cin >> a[i];
    vector<int> s(n+2);
    vector<bool> exact(n+2, false);
    for (int p=n; p>=1; --p) {
        int nxt = p + a[p] + 1;
        if (nxt == n+1) { s[p] = 1; exact[p] = true; }
        else if (nxt > n+1) { s[p] = 1; exact[p] = false; }
        else { s[p] = 1 + s[nxt]; exact[p] = exact[nxt]; }
    }
    for (int i=1; i<n; ++i) {
        int p = i+1;
        int segs = s[p];
        int ans;
        if (exact[p]) ans = (a[i] == segs ? 0 : 1);
        else ans = (a[i] <= segs+1 ? 1 : 2);
        cout << ans << (i==n-1 ? '\n' : ' ');
    }
}

int main() {
    ios::sync_with_stdio(false); cin.tie(0);
    int t; cin >> t;
    while (t--) solve();
    return 0;
}

