    int n; if(!(cin>>n)) return 0;
    vector<int> a(n); for(int i=0;i<n;++i) cin>>a[i];
    const int MAXE=1000000;
    vector<bool> entered(MAXE+1,false), inoffice(MAXE+1,false);
    vector<int> touched; vector<int> days; int bal=0, cur_len=0;
    for(int i=0;i<n;++i){
        int x=a[i];
        if(x>0){
            if(entered[x]){ cout<<-1<<"\n"; return 0; }
            entered[x]=true; inoffice[x]=true; touched.push_back(x); bal++; cur_len++;
        } else {
            int y=-x;
            if(!inoffice[y]){ cout<<-1<<"\n"; return 0; }
            inoffice[y]=false; touched.push_back(y); bal--; cur_len++;
        }
        if(bal==0){
            days.push_back(cur_len); cur_len=0;
            for(int id:touched){ entered[id]=false; inoffice[id]=false; }
            touched.clear();
        }
    }
    if(bal!=0){ cout<<-1<<"\n"; return 0; }
    cout<<days.size()<<"\n";
    for(size_t i=0;i<days.size();++i) cout<<days[i]<<(i+1==days.size()?"":" ");
    cout<<"\n"; return 0;
}

