import sys

def solve():
    a = sys.stdin.readline().strip()
    b = sys.stdin.readline().strip()
    cnt = [0]*10
    for ch in a:
        cnt[int(ch)] += 1
    if len(a) < len(b):
        res = []
        for d in range(9, -1, -1):
            res.append(str(d)*cnt[d])
        print(''.join(res))
        return
    res = []
    tight = True
    for i in range(len(a)):
        bi = int(b[i])
        for d in range(9, -1, -1):
            if cnt[d] > 0 and (i > 0 or d != 0):
                if not tight or d <= bi:
                    cnt[d] -= 1
                    res.append(str(d))
                    if tight and d < bi:
                        tight = False
                        for d2 in range(9, -1, -1):
                            if cnt[d2] > 0:
                                res.append(str(d2)*cnt[d2])
                        break
                    else:
                        break
    print(''.join(res))

if __name__ == '__main__':
    solve()

