using namespace std;

void solve() {
    int n; cin >> n;
    vector<int> a(n+1);
    for (int i = 1; i <= n; i++) cin >> a[i];
    vector<int> dist(n+1, -1);
    queue<int> q;
    dist[1] = 0;
    q.push(1);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        int cur_min = a[u], cur_max = a[u];
        for (int v = u-1; v >= 1; v--) {
            cur_min = min(cur_min, a[v]);
            cur_max = max(cur_max, a[v]);
            if (a[v] == cur_min || a[v] == cur_max) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    q.push(v);
                } else break;
            } else break;
        }
