        vector<int> ops;
        bool ok = true;
        for (int iter = 0; iter < 40; iter++) {
            int mx = *max_element(a.begin(), a.end());
            int mn = *min_element(a.begin(), a.end());
            if (mx == 0) break; // all zero
            if (mx == mn) {
                ops.push_back(mx);
                for (int &v : a) v = abs(v - mx);
                break;
            }
            if ((mx + mn) % 2 != 0) { ok = false; break; }
            int x = (mx + mn) / 2;
            ops.push_back(x);
            for (int &v : a) v = abs(v - x);
        }
        int mx = *max_element(a.begin(), a.end());
        if (ok && mx == 0) {
            cout << ops.size() << "\n";
            for (size_t i = 0; i < ops.size(); i++)
                cout << ops[i] << (i + 1 == ops.size() ? "\n" : " ");
        } else {
            cout << "-1\n";
        }
    }
    return 0;
}

