    for (int i = 0; i < n; i++) {
        long long c;
        string s;
        cin >> c >> s;
        int m = 0;
        for (char ch : s) {
            if (ch == 'A') m |= 1;
            else if (ch == 'B') m |= 2;
            else if (ch == 'C') m |= 4;
        }
        for (int st = 7; st >= 0; st--) {
            if (dp[st] != INF) {
                dp[st | m] = min(dp[st | m], dp[st] + c);
            }
        }
    }
    if (dp[7] >= INF) cout << -1 << endl;
    else cout << dp[7] << endl;
    return 0;
}

