#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

vector<ll> pal;

void gen_pal(ll MAXV) {
    for (int len = 1; len <= 12; ++len) {
        int half = (len + 1) / 2;
        ll start = (len == 1) ? 1 : (ll)pow(10, half - 1);
        ll end = (ll)pow(10, half);
        for (ll i = start; i < end; ++i) {
            string s = to_string(i);
            string t = s; reverse(t.begin(), t.end());
            if (len % 2 == 1) t = t.substr(1);
            string num = s + t;
            ll val = stoll(num);
            if (val <= MAXV) pal.push_back(val);
        }
    }
    sort(pal.begin(), pal.end());
    pal.erase(unique(pal.begin(), pal.end()), pal.end());
}

ll count_primes(ll n) {
    if (n < 2) return 0;
    int sq = sqrt(n);
    vector<bool> isp(sq + 1, true);
    vector<int> primes;
    for (int i = 2; i <= sq; ++i) {
        if (isp[i]) {
            primes.push_back(i);
            for (ll j = (ll)i * i; j <= sq; j += i) isp[j] = false;
        }
    }
    ll cnt = 0, seg = 1000000;
    for (ll low = 2; low <= n; low += seg) {
        ll high = min(low + seg - 1, n);
        vector<bool> block(seg, true);
        for (int p : primes) {
            ll start = max((ll)p * p, ((low + p - 1) / p) * p);
            for (ll j = start; j <= high; j += p) block[j - low] = false;
        }
        for (ll j = low; j <= high; ++j) if (block[j - low]) cnt++;
    }
    return cnt;
}

ll rub(ll n) {
    return upper_bound(pal.begin(), pal.end(), n) - pal.begin();
}

int main() {
    ll p, q; if (!(cin >> p >> q)) return 0;
    ll MAXN = 20000000000LL;
    gen_pal(MAXN);
    ll lo = 1, hi = MAXN, ans = 0;
    while (lo <= hi) {
        ll mid = lo + (hi - lo) / 2;
        ll pi = count_primes(mid);
        ll rb = rub(mid);
        if (q * pi <= p * rb) { ans = mid; lo = mid + 1; }
        else hi = mid - 1;
    }
    if (ans == 0) cout << "Palindromic tree is better than splay tree\n";
    else cout << ans << "\n";
    return 0;
}

