                dy = d - b + 1
                if dy > 0 and dy > req[dx]:
                    req[dx] = dy
    suffix = [0] * (MAX + 2)
    for x in range(MAX, -1, -1):
        suffix[x] = max(suffix[x+1], req[x])
    ans = min(x + suffix[x] for x in range(MAX + 1))
    print(ans)
