#include <iostream>
#include <vector>
#include <queue>
using namespace std;

int n, m;
vector<int> adj[505];
int indeg[505];

bool topo_with_del(int del_v) {
    vector<int> ind(n + 1);
    for (int i = 1; i <= n; ++i) ind[i] = indeg[i];
    if (del_v > 0) ind[del_v]--;          // 模拟删除一条指向 del_v 的边
    queue<int> q;
    for (int i = 1; i <= n; ++i) if (ind[i] == 0) q.push(i);
    int cnt = 0;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        cnt++;
        for (int v : adj[u]) {
            if (--ind[v] == 0) q.push(v);
        }
    }
    return cnt == n;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    if (!(cin >> n >> m)) return 0;
    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        indeg[v]++;
    }
    if (topo_with_del(0)) { cout << "YES\n"; return 0; }
    for (int v = 1; v <= n; ++v) {
        if (indeg[v] > 0 && topo_with_del(v)) {
            cout << "YES\n";
            return 0;
        }
    }
    cout << "NO\n";
    return 0;
}

