        else if (cn == 1 && cnt1 == n - 1) cout << "star topology\n";
        else cout << "unknown topology\n";
    } else if (m == n) {
        bool all2 = true;
        for (int i = 1; i <= n; ++i) if (deg[i] != 2) { all2 = false; break; }
        if (all2) cout << "ring topology\n";
        else cout << "unknown topology\n";
    } else {
        cout << "unknown topology\n";
    }
    return 0;
}

