#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>

using namespace std;

typedef long long ll;
const ll INF = 1e18;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, k;
    if (!(cin >> n >> m >> k)) return 0;
    vector<vector<pair<int, ll>>> adj(n + 1);
    for (int i = 0; i < m; i++) {
        int u, v;
        ll l;
        cin >> u >> v >> l;
        adj[u].push_back({v, l});
        adj[v].push_back({u, l});
    }
    vector<bool> is_storage(n + 1, false);
    vector<int> storages;
    if (k > 0) {
        for (int i = 0; i < k; i++) {
            int a;
            cin >> a;
            is_storage[a] = true;
            storages.push_back(a);
        }
    }
    if (k == 0 || k == n) {
        cout << -1 << endl;
        return 0;
    }
    priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> pq;
    vector<ll> dist(n + 1, INF);
    for (int s : storages) {
        dist[s] = 0;
        pq.push({0, s});
    }
    while (!pq.empty()) {
        auto p = pq.top();
        pq.pop();
        ll d = p.first;
        int u = p.second;
        if (d != dist[u]) continue;
        for (auto& edge : adj[u]) {
            int v = edge.first;
            ll w = edge.second;
            if (dist[v] > d + w) {
                dist[v] = d + w;
                pq.push({dist[v], v});
            }
        }
    }
    ll ans = INF;
    for (int i = 1; i <= n; i++) {
        if (!is_storage[i]) {
            ans = min(ans, dist[i]);
        }
    }
    if (ans == INF) cout << -1 << endl;
    else cout << ans << endl;
    return 0;
}

