        pq.push({0, s});
    }
    while (!pq.empty()) {
        auto p = pq.top();
        pq.pop();
        ll d = p.first;
        int u = p.second;
        if (d != dist[u]) continue;
        for (auto& edge : adj[u]) {
            int v = edge.first;
            ll w = edge.second;
            if (dist[v] > d + w) {
                dist[v] = d + w;
                pq.push({dist[v], v});
            }
        }
    }
    ll ans = INF;
    for (int i = 1; i <= n; i++) {
        if (!is_storage[i]) {
            ans = min(ans, dist[i]);
        }
    }
    if (ans == INF) cout << -1 << endl;
    else cout << ans << endl;
    return 0;
}

