#include <iostream>
#include <vector>
#include <string>
#include <sstream>
#include <algorithm>
using namespace std;

typedef long long ll;

struct SegTree {
    int n;
    vector<ll> mn, lazy;
    SegTree(int _n, const vector<ll>& a) : n(_n), mn(4*_n), lazy(4*_n) {
        build(1, 0, n-1, a);
    }
    void build(int node, int l, int r, const vector<ll>& a) {
        if (l == r) { mn[node] = a[l]; return; }
        int mid = (l+r)/2;
        build(node*2, l, mid, a);
        build(node*2+1, mid+1, r, a);
        mn[node] = min(mn[node*2], mn[node*2+1]);
    }
    void push(int node) {
        if (lazy[node]) {
            mn[node*2] += lazy[node]; lazy[node*2] += lazy[node];
            mn[node*2+1] += lazy[node]; lazy[node*2+1] += lazy[node];
            lazy[node] = 0;
        }
    }
    void update(int node, int l, int r, int ql, int qr, ll v) {
        if (ql <= l && r <= qr) {
            mn[node] += v; lazy[node] += v; return;
        }
        push(node);
        int mid = (l+r)/2;
        if (ql <= mid) update(node*2, l, mid, ql, qr, v);
        if (qr > mid) update(node*2+1, mid+1, r, ql, qr, v);
        mn[node] = min(mn[node*2], mn[node*2+1]);
    }
    ll query(int node, int l, int r, int ql, int qr) {
        if (ql <= l && r <= qr) return mn[node];
        push(node);
        int mid = (l+r)/2;
        ll res = 1e18;
        if (ql <= mid) res = min(res, query(node*2, l, mid, ql, qr));
        if (qr > mid) res = min(res, query(node*2+1, mid+1, r, ql, qr));
        return res;
    }
    void inc(int l, int r, ll v) {
        if (l <= r) update(1, 0, n-1, l, r, v);
        else {
            update(1, 0, n-1, l, n-1, v);
            update(1, 0, n-1, 0, r, v);
        }
    }
    ll rmq(int l, int r) {
        if (l <= r) return query(1, 0, n-1, l, r);
        else return min(query(1, 0, n-1, l, n-1), query(1, 0, n-1, 0, r));
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    if (!(cin >> n)) return 0;
    vector<ll> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    int m;
    cin >> m;
    cin.ignore();
    SegTree st(n, a);
    while (m--) {
        string line;
        getline(cin, line);
        stringstream ss(line);
        int lf, rg, v;
        ss >> lf >> rg;
        if (ss >> v) {
            st.inc(lf, rg, v);
        } else {
            cout << st.rmq(lf, rg) << '\n';
        }
    }
    return 0;
}

