#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false); cin.tie(0);
    int n, k; cin >> n >> k;
    vector<int> p(n+1);
    set<int> unused;
    for (int i=1; i<=n; ++i) unused.insert(i);
    for (int i=1; i<=k; ++i) {
        cin >> p[i];
        unused.erase(p[i]);
    }
    vector<int> st;
    int want = 1;
    for (int i=1; i<=k; ++i) {
        while (!st.empty() && st.back() < p[i]) {
            if (st.back() != want) { cout << -1 << '\n'; return 0; }
            st.pop_back(); want++;
        }
        st.push_back(p[i]);
    }
    for (int i=k+1; i<=n; ++i) {
        int limit;
        if (st.empty()) limit = n;
        else if (st.back() == want) {
            int val = want;
            int idx = (int)st.size()-1;
            while (idx >= 0 && st[idx] == val) { idx--; val++; }
            limit = (idx < 0) ? n : st[idx];
        } else limit = st.back();
        auto it = unused.upper_bound(limit);
        if (it == unused.begin()) { cout << -1 << '\n'; return 0; }
        --it; int x = *it; unused.erase(it);
        while (!st.empty() && st.back() < x) {
            if (st.back() != want) { cout << -1 << '\n'; return 0; }
            st.pop_back(); want++;
        }
        st.push_back(x); p[i] = x;
    }
    for (int i=1; i<=n; ++i) cout << p[i] << (i==n?'\n':' ');
    return 0;
}

