using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    if (!(cin >> n)) return 0;
    vector<int> parent(n+1, 0), temp(n+1);
    vector<vector<int>> child(n+1);
    int root = 0;
    for (int i = 1; i <= n; ++i) {
        cin >> parent[i] >> temp[i];
        if (parent[i] == 0) root = i;
        else child[parent[i]].push_back(i);
    }
    long long total = 0;
    for (int i = 1; i <= n; ++i) total += temp[i];
    if (total % 3 != 0) {
        cout << -1 << "\n";
        return 0;
    }
    long long S = total / 3;
    vector<long long> sub(n+1, 0);
    for (int i = 1; i <= n; ++i) sub[i] = temp[i];
    vector<int> order;
    queue<int> q;
    q.push(root);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        order.push_back(u);
        for (int v : child[u]) q.push(v);
    }
    for (int i = (int)order.size()-1; i >= 0; --i) {
        int u = order[i];
        if (parent[u] != 0) sub[parent[u]] += sub[u];
    }
    vector<int> A;
    for (int i = 1; i <= n; ++i) {
        if (i != root && sub[i] == S) A.push_back(i);
    }
    auto is_ancestor = [&](int u, int v) -> bool {
        int x = v;
        while (x != 0) {
            if (x == u) return true;
            x = parent[x];
        }
        return false;
    };
    for (size_t i = 0; i < A.size(); ++i) {
        for (size_t j = i+1; j < A.size(); ++j) {
            if (!is_ancestor(A[i], A[j]) && !is_ancestor(A[j], A[i])) {
                cout << A[i] << " " << A[j] << "\n";
                return 0;
            }
        }
    }
    for (int y : A) {
        int x = parent[y];
        while (x != 0) {
            if (sub[x] == 2 * S) {
                cout << x << " " << y << "\n";
                return 0;
            }
            x = parent[x];
        }
    }
    cout << -1 << "\n";
    return 0;
}

