#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n, x, y;
    if (!(cin >> n >> x >> y)) return 0;
    vector<long long> dp(n + 1);
    dp[0] = 0;
    for (long long i = 1; i <= n; ++i) {
        dp[i] = dp[i - 1] + x;
        if (i % 2 == 0) {
            dp[i] = min(dp[i], dp[i / 2] + y);
        } else {
            dp[i] = min(dp[i], dp[i / 2] + y + x);
            dp[i] = min(dp[i], dp[i / 2 + 1] + y + x);
        }
    }
    cout << dp[n] << "\n";
    return 0;
}

