#include <iostream>
#include <string>
#include <unordered_set>

using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    if (!(cin >> n >> m)) return 0;
    unordered_set<string> dict;
    dict.reserve(300000);
    for (int i = 0; i < n; ++i) {
        string s;
        cin >> s;
        dict.insert(move(s));
    }
    for (int i = 0; i < m; ++i) {
        string s;
        cin >> s;
        bool found = false;
        for (size_t j = 0; j < s.size(); ++j) {
            char orig = s[j];
            for (char c : {'a', 'b', 'c'}) {
                if (c == orig) continue;
                s[j] = c;
                if (dict.count(s)) {
                    found = true;
                    break;
                }
            }
            s[j] = orig;
            if (found) break;
        }
        cout << (found ? "YES" : "NO") << '\n';
    }
    return 0;
}

