import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    adj = [[] for _ in range(n + 1)]
    deg = [0] * (n + 1)
    for _ in range(n - 1):
        u = int(next(it)); v = int(next(it))
        adj[u].append(v); adj[v].append(u)
        deg[u] += 1; deg[v] += 1
    k = sum(1 for v in range(2, n + 1) if deg[v] == 1)
    order = [int(next(it)) for _ in range(k)]
    pos = [0] * (n + 1)
    for i, leaf in enumerate(order):
        pos[leaf] = i
    parent = [0] * (n + 1)
    depth = [0] * (n + 1)
    stack = [1]
    dfs_order = []
    while stack:
        u = stack.pop()
        dfs_order.append(u)
        for v in adj[u]:
            if v != parent[u]:
                parent[v] = u
                depth[v] = depth[u] + 1
                stack.append(v)
    sub_leaves = [[] for _ in range(n + 1)]
    for u in dfs_order[::-1]:
        if u != 1 and deg[u] == 1:
            sub_leaves[u].append(pos[u])
        for v in adj[u]:
            if v != parent[u]:
                sub_leaves[u].extend(sub_leaves[v])
    ok = True
    for u in range(1, n + 1):
        lst = sorted(sub_leaves[u])
        for i in range(len(lst)):
            if lst[i] != lst[0] + i:
                ok = False
                break
        if not ok:
            break
    if not ok:
        print(-1)
        return
    def get_path(a, b):
        if a == b:
            return [a]
        path_a = [a]
        while depth[a] > depth[b]:
            a = parent[a]; path_a.append(a)
        if a == b:
            return path_a
        path_b = [b]
        while depth[b] > depth[a]:
            b = parent[b]; path_b.append(b)
        while a != b:
            a = parent[a]; path_a.append(a)
            b = parent[b]; path_b.append(b)
        path_b.pop()
        path_b.reverse()
        return path_a + path_b
    cur = 1
    out = [1]
    for L in order:
        path = get_path(cur, L)
        for node in path[1:]:
            out.append(node)
        cur = L
    path = get_path(cur, 1)
    for node in path[1:]:
        out.append(node)
    print(' '.join(map(str, out)))

if __name__ == '__main__':
    solve()

